var newest = [{"id":"20261121212957559800","time":"2026-11-21 21:29:57","type":0,"data":{"pic":"","title":"","source":"","content":"<b>据伊朗国家媒体：伊朗军方称，其防空导弹在海湾上空击中一架美军F-16战斗机并造成损伤，迫使该机紧急降落。美方暂未证实这一说法。</b>","source_link":"","exclusive_to":[]},"important":0,"tags":[],"channel":[1,3,2],"remark":[]},{"id":"20261121210605065800","time":"2026-11-21 21:06:05","type":0,"data":{"pic":"","title":"","source":"","content":"沙特解除吉赞地区危险警报。","source_link":"","exclusive_to":[]},"important":0,"tags":[],"channel":[1],"remark":[]},{"id":"20261121210458166800","time":"2026-11-21 21:04:58","type":0,"data":{"pic":"","title":"","source":"","content":"【泽连斯基会见英国国防大臣 讨论乌防空能力建设】金十数据11月21日讯，当地时间11月21日，乌克兰总统泽连斯基在基辅会见到访的英国国防大臣斯特里廷。双方重点就乌防空能力建设、“爱国者”防空系统所用拦截弹供应、联合武器生产、远程打击能力等议题进行磋商。在联合武器生产与远程打击能力建设方面，双方认为该领域具备深化合作的空间。通过联合生产与技术协作，能够助力乌克兰推进本土导弹研发计划。此外，泽连斯基还表示，英国提供的新一批国防与人道主义援助总额超过5亿英镑。","source_link":"","exclusive_to":[]},"important":0,"tags":[],"channel":[1],"remark":[]},{"id":"20261121210040528800","time":"2026-11-21 21:00:40","type":0,"data":{"pic":"","title":"","source":"","content":"沙特民防部门发布警报，提醒吉赞地区可能存在危险。","source_link":"","exclusive_to":[]},"important":0,"tags":[],"channel":[1],"remark":[]},{"id":"20261121205232513800","time":"2026-11-21 20:52:32","type":0,"data":{"pic":"","title":"","source":"","content":"【欧盟领导人会议主席提议进一步削减2028-2034年欧盟预算草案，并建议开征数字税】金十数据11月21日讯，欧盟领导人峰会主席周六提议进一步削减欧盟委员会提出的2028-2034年欧盟预算草案，并建议开辟新的收入来源，包括征收数字税，以帮助为欧盟政策提供资金。作为欧盟领导人峰会主席的安东尼奥·科斯塔提出的削减方案，将使七年期预算总额较爱尔兰轮值主席国于10月提交的提案减少400亿欧元，降至1.582万亿欧元；与欧盟委员会最初的提案相比，则减少1806亿欧元。科斯塔的提案主要削减了“欧洲竞争力基金”（旨在帮助欧洲工业增强与中国和美国的竞争力）、国防及对外支出。与爱尔兰的折中提案相比，农业和区域凝聚力方面的资金相对得到保障。尽管如此，法国批评新预算数字未能充分保障农民利益，而欧洲议会首席预算谈判代表齐格弗里德·穆雷桑则表示，这些数字是倒退的一步。“该提案对议会而言是不可接受的，也不能作为我们批准的依据。欧盟预算是一项投资预算。削减、再削减，以及额外的削减，绝非投资战略，”他说道。","source_link":"","exclusive_to":[]},"important":0,"tags":[],"channel":[1,3],"remark":[]}];